param(
 [Parameter(Mandatory=$true)][string]$Destination,
 [switch]$PrepareBuild,
 [switch]$Target,
 [switch]$Execute,
 [string]$TargetApprovalReceipt
)
$ErrorActionPreference='Stop'
$repo=(Resolve-Path (Join-Path $PSScriptRoot '..')).Path
$dest=[IO.Path]::GetFullPath($Destination)
if($dest.StartsWith($repo,[StringComparison]::OrdinalIgnoreCase)){throw 'Isolated destination must be outside the repository.'}
if(Test-Path -LiteralPath $dest){throw 'Isolated destination already exists; use a new timestamped path.'}
New-Item -ItemType Directory -Path $dest|Out-Null
$inputScopes=@('src','scripts','tests','public','vendor');foreach($scope in $inputScopes){$reparse=Get-ChildItem -LiteralPath (Join-Path $repo $scope) -Recurse -Force -Attributes ReparsePoint -ErrorAction SilentlyContinue;if($reparse){throw "Input scope contains reparse point: $($reparse[0].FullName)"}}
$null=& robocopy $repo $dest /E /XJ /XD .git node_modules .audit-tmp dist
if($LASTEXITCODE-ge8){throw "robocopy failed: $LASTEXITCODE"}
$null=& robocopy (Join-Path $repo 'node_modules') (Join-Path $dest 'node_modules') /E /XJ /XD .vite .cache cache .parcel-cache
if($LASTEXITCODE-ge8){throw "dependency copy failed: $LASTEXITCODE"}
$route=Join-Path $dest 'scripts/current-evidence.mjs';$text=[IO.File]::ReadAllText($route);if(!$text.Contains("CURRENT_EVIDENCE='docs/content/r19'")){throw 'Isolated current-evidence destination is not R19.'}
$stamp=(Get-Date).ToUniversalTime().ToString('yyyyMMddTHHmmssfffZ');$logDir=Join-Path $dest 'docs/content/r19/commands';New-Item -ItemType Directory -Force -Path $logDir|Out-Null
$copyRows=@();foreach($scope in $inputScopes){Get-ChildItem -LiteralPath (Join-Path $repo $scope) -Recurse -File|ForEach-Object{$rel=$_.FullName.Substring($repo.Length+1);$copy=Join-Path $dest $rel;$sourceHash=(Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256).Hash.ToLower();$copyHash=(Get-FileHash -LiteralPath $copy -Algorithm SHA256).Hash.ToLower();if($sourceHash-ne$copyHash-or$_.Length-ne(Get-Item -LiteralPath $copy).Length){throw "Isolated copy mismatch: $rel"};$copyRows+=[ordered]@{path=$rel.Replace('\','/');sha256=$sourceHash;bytes=$_.Length;media=[bool]($_.Extension -match '^\.(png|webp|jpg|jpeg|gif|mp3|wav|mp4)$')}}}
$fixedRows=@();foreach($rel in @('package.json','package-lock.json','README.md','LICENSE','CREDITS.md')){$source=Join-Path $repo $rel;$copy=Join-Path $dest $rel;$hash=(Get-FileHash -LiteralPath $source -Algorithm SHA256).Hash.ToLower();if($hash-ne(Get-FileHash -LiteralPath $copy -Algorithm SHA256).Hash.ToLower()){throw "Fixed copy mismatch: $rel"};$fixedRows+=[ordered]@{path=$rel;sha256=$hash;bytes=(Get-Item $source).Length}}
$copyClosure=[ordered]@{status='VERIFIED_COPY_CLOSURE';captured_utc=(Get-Date).ToUniversalTime().ToString('o');source=$repo;destination=$dest;files=@($copyRows+$fixedRows);file_count=$copyRows.Count+$fixedRows.Count;media_file_count=@($copyRows|Where-Object media).Count;nonmedia_file_count=@($copyRows|Where-Object {-not $_.media}).Count+$fixedRows.Count}
$copyClosurePath=Join-Path $logDir "$stamp-copy-closure.json";[IO.File]::WriteAllText($copyClosurePath,($copyClosure|ConvertTo-Json -Depth 5)+"`n",[Text.UTF8Encoding]::new($false))
$docRows=@();Get-ChildItem -LiteralPath (Join-Path $repo 'docs') -Recurse -File|ForEach-Object{$rel=$_.FullName.Substring($repo.Length+1);$copy=Join-Path $dest $rel;$sourceHash=(Get-FileHash -LiteralPath $_.FullName -Algorithm SHA256).Hash.ToLower();$copyHash=(Get-FileHash -LiteralPath $copy -Algorithm SHA256).Hash.ToLower();if($sourceHash-ne$copyHash-or$_.Length-ne(Get-Item -LiteralPath $copy).Length){throw "Historical docs copy mismatch: $rel"};$docRows+=[ordered]@{path=$rel.Replace('\','/');sha256=$sourceHash;bytes=$_.Length}}
$docTotal=($docRows|ForEach-Object{[int64]$_['bytes']}|Measure-Object -Sum).Sum;$docClosure=[ordered]@{status='VERIFIED_HISTORICAL_DOC_INPUT_COPY';captured_utc=(Get-Date).ToUniversalTime().ToString('o');policy='Clone writers may mutate clone docs; original repo docs must remain byte-identical to this closure.';source=$repo;destination=$dest;file_count=$docRows.Count;total_bytes=$docTotal;files=$docRows};$docClosurePath=Join-Path $logDir "$stamp-doc-input-closure.json";[IO.File]::WriteAllText($docClosurePath,($docClosure|ConvertTo-Json -Depth 5)+"`n",[Text.UTF8Encoding]::new($false))
$dependencyFiles=Get-ChildItem -LiteralPath (Join-Path $dest 'node_modules') -Recurse -File;$dependencyClosure=[ordered]@{status='VERIFIED_OWNED_DEPENDENCY_COPY';source=(Join-Path $repo 'node_modules');destination=(Join-Path $dest 'node_modules');excluded_cache_names=@('.vite','.cache','cache','.parcel-cache');file_count=$dependencyFiles.Count;total_bytes=($dependencyFiles|Measure-Object Length -Sum).Sum;files=@($dependencyFiles|ForEach-Object{[ordered]@{path=$_.FullName.Substring((Join-Path $dest 'node_modules').Length+1).Replace('\','/');sha256=(Get-FileHash $_.FullName -Algorithm SHA256).Hash.ToLower();bytes=$_.Length}})};$dependencyClosurePath=Join-Path $logDir "$stamp-dependency-closure.json";[IO.File]::WriteAllText($dependencyClosurePath,($dependencyClosure|ConvertTo-Json -Depth 5)+"`n",[Text.UTF8Encoding]::new($false))
$prepared=[ordered]@{status='PREPARED';created_utc=(Get-Date).ToUniversalTime().ToString('o');source=$repo;destination=$dest;current_evidence='docs/content/r19';owned_dependency_copy=$dependencyClosurePath;copy_closure_path=$copyClosurePath;copy_closure_sha256=(Get-FileHash $copyClosurePath -Algorithm SHA256).Hash.ToLower();doc_input_closure_path=$docClosurePath;doc_input_closure_sha256=(Get-FileHash $docClosurePath -Algorithm SHA256).Hash.ToLower();doc_input_policy='No exclusions; complete docs tree copied and initially matched. Clone output changes allowed; original docs protected.';preload='scripts/r19-software-renderer-preload.cjs';prepare_build_requested=[bool]$PrepareBuild;target_requested=[bool]$Target;full_requested=[bool]$Execute}
[IO.File]::WriteAllText((Join-Path $logDir "$stamp-prepared.json"),($prepared|ConvertTo-Json -Depth 4)+"`n",[Text.UTF8Encoding]::new($false))
if(!$PrepareBuild-and!$Target-and!$Execute){Write-Output "PREPARED=$dest";exit 0}
if(@($PrepareBuild,$Target,$Execute).Where({[bool]$_}).Count-gt1){throw 'Choose PrepareBuild, Target or Execute.'}
$oldNodeOptions=$env:NODE_OPTIONS;$oldRenderer=$env:R19_RENDERER_DIR
try{
 $env:NODE_OPTIONS="--require=$((Join-Path $dest 'scripts/r19-software-renderer-preload.cjs'))";$env:R19_RENDERER_DIR=Join-Path $dest 'docs/content/r19/renderer'
 Push-Location $dest;try{& node scripts/content-r19-source-closure.mjs;$closureExit=$LASTEXITCODE}finally{Pop-Location};if($closureExit-ne0){exit $closureExit};$closurePath=Join-Path $dest 'docs/content/r19/current-source-closure.json';$closureHash=(Get-FileHash $closurePath -Algorithm SHA256).Hash.ToLower();$sourceBefore=(Get-Content $closurePath -Raw -Encoding utf8|ConvertFrom-Json).aggregateSHA256
 if($Execute){if(!$TargetApprovalReceipt-or!(Test-Path -LiteralPath $TargetApprovalReceipt -PathType Leaf)){throw 'Full execution requires target approval JSON.'};$approval=Get-Content $TargetApprovalReceipt -Raw -Encoding utf8|ConvertFrom-Json;if($approval.status-ne'APPROVED'-or$approval.sourceAggregateSHA256-ne$sourceBefore-or!(Test-Path -LiteralPath $approval.targetReceiptPath -PathType Leaf)-or(Get-FileHash $approval.targetReceiptPath -Algorithm SHA256).Hash.ToLower()-ne$approval.targetReceiptSHA256){throw 'Target approval does not bind current source aggregate and target receipt.'}}
 $jobs=$(if($PrepareBuild){@(@{name='prepare-build';args=@('run','build')},@{name='prepare-unit';args=@('run','test:unit:r19')})}elseif($Target){@(@{name='target-build';args=@('run','build')},@{name='target-unit';args=@('run','test:unit:r19')},@{name='target-browser';args=@('run','test:content:r19')})}else{@(@{name='full-unit';args=@('test')},@{name='full-verify';args=@('run','verify')})})
 foreach($job in $jobs){
  $log=Join-Path $logDir "$stamp-$($job.name).txt";$started=(Get-Date).ToUniversalTime().ToString('o');Push-Location $dest;try{& npm @($job.args) 2>&1|Tee-Object -FilePath $log;$native=$LASTEXITCODE;& node scripts/content-r19-source-closure.mjs --verify|Out-Null;$closureExit=$LASTEXITCODE}finally{Pop-Location};$copyExit=0;foreach($row in $copyClosure.files){$original=Join-Path $repo $row.path;$isolated=Join-Path $dest $row.path;if(!(Test-Path -LiteralPath $original -PathType Leaf)-or!(Test-Path -LiteralPath $isolated -PathType Leaf)-or(Get-FileHash $original -Algorithm SHA256).Hash.ToLower()-ne$row.sha256-or(Get-FileHash $isolated -Algorithm SHA256).Hash.ToLower()-ne$row.sha256){$copyExit=1;break}};$docsExit=0;foreach($row in $docClosure.files){$original=Join-Path $repo $row.path;if(!(Test-Path -LiteralPath $original -PathType Leaf)-or(Get-FileHash $original -Algorithm SHA256).Hash.ToLower()-ne$row.sha256){$docsExit=1;break}};$sourceAfter=$(if($closureExit-eq0-and$copyExit-eq0-and$docsExit-eq0){$sourceBefore}else{'CHANGED'});$receipt=[ordered]@{status=$(if($native-eq0-and$closureExit-eq0-and$copyExit-eq0-and$docsExit-eq0){'VERIFIED'}else{'BLOCKED'});command="npm $($job.args -join ' ')";started_utc=$started;finished_utc=(Get-Date).ToUniversalTime().ToString('o');exit_code=$native;stdout_stderr_path=$log;stdout_stderr_sha256=(Get-FileHash $log -Algorithm SHA256).Hash.ToLower();source_closure_sha256=$closureHash;copy_closure_sha256=(Get-FileHash $copyClosurePath -Algorithm SHA256).Hash.ToLower();doc_input_closure_sha256=(Get-FileHash $docClosurePath -Algorithm SHA256).Hash.ToLower();source_before_sha256=$sourceBefore;source_after_sha256=$sourceAfter;original_docs_after='UNCHANGED';renderer_preload_sha256=(Get-FileHash (Join-Path $dest 'scripts/r19-software-renderer-preload.cjs') -Algorithm SHA256).Hash.ToLower()};[IO.File]::WriteAllText((Join-Path $logDir "$stamp-$($job.name).json"),($receipt|ConvertTo-Json -Depth 5)+"`n",[Text.UTF8Encoding]::new($false));if($native-ne0-or$closureExit-ne0-or$copyExit-ne0-or$docsExit-ne0){exit $(if($native-ne0){$native}else{1})}
 }
}finally{$env:NODE_OPTIONS=$oldNodeOptions;$env:R19_RENDERER_DIR=$oldRenderer}
